import java.util.Scanner;

public class DifferentTypesOfInput {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);

        // Write your program here
        System.out.println("Give a string:");
        String firstStr = scan.nextLine();

        System.out.println("Give an integer:");
        int firstInt = Integer.valueOf(scan.nextLine());

        System.out.println("Give a double:");
        double firstDouble = Double.valueOf(scan.nextLine());

        System.out.println("Give a boolean:");
        boolean firstBool = Boolean.valueOf(scan.nextLine());

        System.out.println("You gave the string " + firstStr);
        System.out.println("You gave the integer " + firstInt);
        System.out.println("You gave the double " + firstDouble);
        System.out.println("You gave the boolean " + firstBool);

    }
}
